projects=[]
def add(id,name,lon,lat,year,match,tag,unlock,ask,owners,pages,primary=False):
 row=next((r for r in cap if r['name']==match),None)
 if row is None and match: row=next((r for r in cap if match in r['name']),None)
 if match and row is None:print('NO MATCH',id,match)
 projects.append(dict(id=id,name=name,lon=lon,lat=lat,year=year,category=tag,unlock=unlock,ask=ask,owners=owners,pages=pages,primary=primary,capitalId=row['id'] if row else None,cost=row['cost'] if row else None,capitalName=row['name'] if row else None,pdfPage=row['pdfPage'] if row else None))
